insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-264","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Association of solute molecules makes the observed molar mass","options":["larger than the true formula mass","smaller than the true formula mass","unchanged","zero"],"answer_index":0,"explanation":"Fewer particles are present, so the colligative effect is smaller and $M_{\\mathrm{obs}} = M / i$ is larger (i < 1).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-265","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissociation of a solute makes the observed molar mass","options":["smaller than the true formula mass","larger than the true formula mass","infinite","equal to $K_b$"],"answer_index":0,"explanation":"More particles raise the colligative effect, so $M_{\\mathrm{obs}} = M / i$ falls below M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-266","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Abnormal molar mass arises when","options":["the solute associates or dissociates","the solvent is merely wet","the temperature is 25 °C","$K_H$ is large"],"answer_index":0,"explanation":"Either process changes the particle count, so the molar mass inferred from a colligative law is abnormal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-267","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The relation connecting i, the number of particles n from one formula unit, and the degree of dissociation $\\alpha$ is","options":["$i = 1 + (n - 1)\\alpha$","$i = n\\alpha$","$i = 1 - n\\alpha$","$i = \\alpha / n$"],"answer_index":0,"explanation":"Each dissociated unit adds (n − 1) extra particles, so i − 1 = (n − 1)$\\alpha$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-268","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzoic acid in benzene often shows i less than 1 because it","options":["dimerises","ionises into four ions","evaporates completely","becomes a metal"],"answer_index":0,"explanation":"Hydrogen-bonded dimers reduce the particle count, so i < 1 and $M_{\\mathrm{obs}}$ is high.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-269","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For Al2(SO4)3, complete dissociation would give i of","options":["5","3","2","4"],"answer_index":0,"explanation":"2 Al³⁺ + 3 SO₄²⁻ = five ions per formula unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-270","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If i = 2 for a binary electrolyte AB, the degree of dissociation is","options":["1 (complete)","0.5","0","2"],"answer_index":0,"explanation":"i = 1 + (2 − 1)$\\alpha$ = 1 + $\\alpha$, so i = 2 means $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-271","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed $\\Delta T_f$ divided by the $\\Delta T_f$ calculated with the theoretical molar mass equals","options":["i","$K_b$","$K_f$","$\\pi$"],"answer_index":0,"explanation":"That ratio is the definition of the van’t Hoff factor from freezing-point data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-272","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"K4[Fe(CN)6] on complete ionisation yields particles numbering","options":["5","4","2","1"],"answer_index":0,"explanation":"Four K⁺ ions plus [Fe(CN)6]⁴⁻ give five particles, so i = 5 when fully split.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal"},{"id":"che-so-273","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A binary electrolyte is 60% dissociated. The van’t Hoff factor is","options":["1.60","2.00","0.60","1.00"],"answer_index":0,"explanation":"i = 1 + (2 − 1)(0.60) = 1.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-274","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Acetic acid appears to have molar mass 120 g mol⁻¹ in benzene (true M = 60). Then i equals","options":["0.50","2.0","1.0","1.5"],"answer_index":0,"explanation":"i = $M_{\\mathrm{true}} / M_{\\mathrm{obs}} = 60/120 = 0.50$ (essentially complete dimerisation).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-275","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"BaCl2 is 80% dissociated. With n = 3, i is","options":["2.60","3.00","0.80","1.80"],"answer_index":0,"explanation":"i = 1 + (3 − 1)(0.80) = 2.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-276","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solute that should give $\\Delta T_b = 0.20$ K actually gives 0.30 K. The van’t Hoff factor is","options":["1.5","0.67","2.0","0.20"],"answer_index":0,"explanation":"i = 0.30 / 0.20 = 1.5.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-277","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed molar mass of NaCl in water is 30 g mol⁻¹ (formula mass 58.5). The factor i is nearest","options":["1.95","0.51","3.00","1.00"],"answer_index":0,"explanation":"i = 58.5 / 30 = 1.95, close to complete dissociation into two ions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-278","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For dimerisation with $\\alpha = 0.40$, i equals","options":["0.80","1.40","0.40","2.00"],"answer_index":0,"explanation":"i = 1 − $\\alpha$(1 − 1/n) = 1 − 0.40/2 = 0.80.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal"},{"id":"che-so-279","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 m aqueous Ca(NO3)2 solution is 70% dissociated. Using $K_f = 1.86$ K kg mol⁻¹, the freezing-point depression is nearest","options":["0.45 K","0.19 K","0.56 K","1.86 K"],"answer_index":0,"explanation":"n = 3, i = 1 + 2 × 0.70 = 2.40; $\\Delta T_f = 2.40 \\times 1.86 \\times 0.10 = 0.446$ K ≈ 0.45 K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal"},{"id":"che-so-280","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.050 M weak electrolyte is 40% dissociated into two ions. At 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹), osmotic pressure is nearest","options":["1.72 atm","1.23 atm","0.050 atm","2.46 atm"],"answer_index":0,"explanation":"i = 1.40; $\\pi = iCRT = 1.40 \\times 0.050 \\times 0.0821 \\times 300 \\approx 1.72$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal"},{"id":"che-so-281","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two liquids that dissolve in each other in all proportions are called","options":["completely miscible","immiscible","partially miscible","always azeotropic"],"answer_index":0,"explanation":"Complete miscibility means a single liquid phase at every composition.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope"},{"id":"che-so-282","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Phenol and water below the consolute temperature form","options":["two liquid layers (partially miscible)","a single ideal gas","a solid alloy","an azeotrope only"],"answer_index":0,"explanation":"They are the usual Intermediate example of a pair with a limited mutual solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope"},{"id":"che-so-283","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An azeotrope is a constant-boiling mixture whose vapour has","options":["the same composition as the boiling liquid","a composition richer in the less volatile component always","zero pressure","only water"],"answer_index":0,"explanation":"Liquid and vapour compositions coincide, so simple distillation does not change the composition.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-264","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-265","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-266","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-267","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-268","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-269","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-270","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-271","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-272","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-273","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-274","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-275","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-276","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-277","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-278","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-279","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-280","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-281","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-282","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-283","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
